-- REVIEW BEFORE RUNNING: this is a destructive, one-time demo reset.
-- It removes the guarded QRoute demo route, its route-stop links, demo stops,
-- demo terminals, and route-specific rail fares, then seeds one MRT-3 sample
-- segment in Quezon City. It does not reset ID sequences or delete transport
-- types/variants, fare areas, general fare rules, or fare discount rules.
-- There is no roads table; displayed road geometry is generated by the app.
--
-- The fare guide below is a secondary source and may not reflect current
-- fares. The student/PWD discounts are copied from the app's configured 20%
-- policy but remain unverified for rail. Review this script before running.
-- Run the whole script in one transaction. It aborts unless the database
-- matches the exact demo-only preconditions below or has no transit rows.

begin;

do $seed$
declare
  v_demo_route_id bigint;
  v_train_type_id bigint;
  v_rail_variant_id bigint;
  v_new_route_id bigint;
  v_stop_id bigint;
  v_stop_ids bigint[] := array[]::bigint[];
  v_station record;
  v_from_index integer;
  v_to_index integer;
  v_station_gap integer;
  v_station_count integer := 4;
  v_fare numeric(8, 2);
  v_match_count integer;
  v_is_empty boolean;
begin
  v_is_empty := not exists (select 1 from public.routes)
    and not exists (select 1 from public.route_stops)
    and not exists (select 1 from public.stops)
    and not exists (select 1 from public.terminals);

  if not v_is_empty and (
    (select count(*) from public.routes) <> 1
    or (select count(*) from public.stops) <> 3
    or (select count(*) from public.terminals) <> 2
    or (
      select count(*)
      from public.routes
      where name = 'Demo QC Jeepney Route'
        and transport_type_id = (
          select id from public.transport_types where name = 'Jeepney'
        )
        and variant_id = (
          select id
          from public.transport_variants
          where code = 'traditional_jeepney'
            and fare_model = 'distance'
        )
        and is_active
        and is_approved
        and moderation_status = 'approved'
        and not is_banned
        and not is_deleted
    ) <> 1
    or (
      select count(*)
      from public.stops
      where name in ('Demo Stop A', 'Demo Stop B', 'Demo Train Station')
    ) <> 3
    or (
      select count(*)
      from public.terminals
      where name in ('Demo North Terminal', 'Demo Central Terminal')
    ) <> 2
  ) then
    raise exception
      'Reset aborted: expected the approved QRoute demo dataset or a completely empty transit dataset.';
  end if;

  select id
  into v_demo_route_id
  from public.routes
  where name = 'Demo QC Jeepney Route';

  if not v_is_empty and (
    (select count(*) from public.route_stops) <> 5
    or (select count(*) from public.route_stops where route_id = v_demo_route_id) <> 5
    or exists (
      select 1
      from public.route_stops rs
      left join public.terminals t on t.id = rs.terminal_id
      left join public.stops s on s.id = rs.stop_id
      where rs.route_id = v_demo_route_id
        and not (
          (rs.stop_order = 1 and t.name = 'Demo North Terminal')
          or (rs.stop_order = 2 and s.name = 'Demo Stop A')
          or (rs.stop_order = 3 and s.name = 'Demo Stop B')
          or (rs.stop_order = 4 and s.name = 'Demo Train Station')
          or (rs.stop_order = 5 and t.name = 'Demo Central Terminal')
        )
    )
    or (
      select count(*)
      from public.route_stops rs
      left join public.terminals t on t.id = rs.terminal_id
      left join public.stops s on s.id = rs.stop_id
      where rs.route_id = v_demo_route_id
        and (
          (rs.stop_order = 1 and t.name = 'Demo North Terminal')
          or (rs.stop_order = 2 and s.name = 'Demo Stop A')
          or (rs.stop_order = 3 and s.name = 'Demo Stop B')
          or (rs.stop_order = 4 and s.name = 'Demo Train Station')
          or (rs.stop_order = 5 and t.name = 'Demo Central Terminal')
        )
    ) <> 5
    or exists (
      select 1
      from public.rail_fares
      where route_id = v_demo_route_id
    )
  ) then
    raise exception
      'Reset aborted: the demo route stops or its route-specific rail fares differ from the expected sample.';
  end if;

  select count(*)
  into v_match_count
  from public.transport_types
  where name = 'Train';
  if v_match_count <> 1 then
    raise exception
      'Reset aborted: expected exactly one Train transport type, found %.',
      v_match_count;
  end if;

  select id
  into v_train_type_id
  from public.transport_types
  where name = 'Train';

  select count(*)
  into v_match_count
  from public.transport_variants
  where code = 'rail'
    and fare_model = 'matrix'
    and transport_type_id = v_train_type_id
    and is_active;
  if v_match_count <> 1 then
    raise exception
      'Reset aborted: expected exactly one active rail matrix variant for Train, found %.',
      v_match_count;
  end if;

  select id
  into v_rail_variant_id
  from public.transport_variants
  where code = 'rail'
    and fare_model = 'matrix'
    and transport_type_id = v_train_type_id
    and is_active;

  if exists (select 1 from public.rail_fares)
    or exists (
      select 1
      from public.fare_discount_rules
      where variant_id = v_rail_variant_id
    )
    or exists (
      select 1
      from public.map_images mi
      left join public.stops s on s.id = mi.stop_id
      left join public.terminals t on t.id = mi.terminal_id
      where s.name in ('Demo Stop A', 'Demo Stop B', 'Demo Train Station')
        or t.name in ('Demo North Terminal', 'Demo Central Terminal')
    )
  then
    raise exception
      'Reset aborted: existing rail fares, rail discount rules, or linked map images need review before seeding.';
  end if;

  delete from public.rail_fares
  where route_id = v_demo_route_id;
  delete from public.route_stops
  where route_id = v_demo_route_id;
  delete from public.routes
  where id = v_demo_route_id;
  delete from public.stops
  where name in ('Demo Stop A', 'Demo Stop B', 'Demo Train Station');
  delete from public.terminals
  where name in ('Demo North Terminal', 'Demo Central Terminal');

  for v_station in
    select *
    from (values
      (
        'North Avenue'::text,
        1::integer,
        14.6521641::double precision,
        121.0322409::double precision,
        'https://www.openstreetmap.org/way/222628892'::text
      ),
      (
        'Quezon Avenue'::text,
        2::integer,
        14.6422956::double precision,
        121.0387658::double precision,
        'https://www.openstreetmap.org/way/128196488'::text
      ),
      (
        'GMA Kamuning'::text,
        3::integer,
        14.6353731::double precision,
        121.0432650::double precision,
        'https://www.openstreetmap.org/way/30262758'::text
      ),
      (
        'Araneta-Cubao'::text,
        4::integer,
        14.6199760::double precision,
        121.0510969::double precision,
        'https://www.openstreetmap.org/node/14139719118'::text
      )
    ) as stations(name, station_order, latitude, longitude, osm_url)
    order by station_order
  loop
    insert into public.stops (
      name,
      description,
      stop_type,
      latitude,
      longitude,
      is_active,
      is_approved,
      moderation_status,
      moderation_note,
      moderated_at,
      is_banned,
      is_deleted
    )
    values (
      v_station.name,
      format(
        'MRT-3 station. Coordinates from OpenStreetMap: %s. Map data © OpenStreetMap contributors.',
        v_station.osm_url
      ),
      'train_station',
      v_station.latitude,
      v_station.longitude,
      true,
      true,
      'approved',
      'Seeded from sourced MRT-3 sample data.',
      now(),
      false,
      false
    )
    returning id into v_stop_id;

    v_stop_ids := array_append(v_stop_ids, v_stop_id);
  end loop;

  insert into public.routes (
    name,
    transport_type_id,
    variant_id,
    is_active,
    is_approved,
    moderation_status,
    moderation_note,
    moderated_at,
    is_banned,
    is_deleted
  )
  values (
    'MRT-3 Quezon City Sample Segment',
    v_train_type_id,
    v_rail_variant_id,
    true,
    true,
    'approved',
    'Quezon City sample segment; station locations and fares include source notes.',
    now(),
    false,
    false
  )
  returning id into v_new_route_id;

  for v_from_index in 1..v_station_count loop
    insert into public.route_stops (route_id, stop_order, stop_id)
    values (v_new_route_id, v_from_index, v_stop_ids[v_from_index]);
  end loop;

  for v_from_index in 1..(v_station_count - 1) loop
    for v_to_index in (v_from_index + 1)..v_station_count loop
      v_station_gap := v_to_index - v_from_index;
      v_fare := case
        when v_station_gap <= 2 then 13
        else 16
      end;

      insert into public.rail_fares (
        route_id,
        from_stop_id,
        to_stop_id,
        stored_value_fare,
        single_journey_fare,
        effective_from,
        source_name,
        source_url,
        verification_status,
        notes
      )
      values (
        v_new_route_id,
        v_stop_ids[v_from_index],
        v_stop_ids[v_to_index],
        v_fare,
        v_fare,
        date '2015-01-04',
        'MRT-3 Fare Guide (MRT3.com; secondary source)',
        'https://mrt3.com/index.php/menu-fare-tickets.html',
        'secondary',
        format(
          'Base fare by %s station gap. Secondary source; confirm against a current official matrix.',
          v_station_gap
        )
      );
    end loop;
  end loop;

  insert into public.fare_discount_rules (
    variant_id,
    passenger_category,
    discount_percent,
    effective_from,
    source_name,
    source_url,
    verification_status,
    is_deleted
  )
  values
    (
      v_rail_variant_id,
      'student',
      20,
      date '2026-10-27',
      'Republic Act No. 11314 (Student Fare Discount Act of 2019)',
      'https://www.officialgazette.gov.ph/2019/04/17/republic-act-no-11314/',
      'unverified',
      false
    ),
    (
      v_rail_variant_id,
      'pwd',
      20,
      date '2026-10-27',
      'Republic Act No. 10754 (Expanded Benefits and Privileges of Persons with Disability)',
      'https://www.officialgazette.gov.ph/2016/03/23/republic-act-no-10754/',
      'unverified',
      false
    );
end
$seed$;

commit;
